insert into public.anuncios
    (user_id, titulo, categoria, descricao, cidade, cep, logradouro, numero, complemento, bairro,
     endereco, telefone, whatsapp, instagram, site, horarios, imagem_url, fotos, plano, status)
select null, n.titulo, n.categoria, n.descricao, 'alfenas', n.cep, n.logradouro, n.numero, n.complemento, n.bairro,
       concat_ws(' - ', n.logradouro || ', ' || n.numero, n.complemento, n.bairro),
       n.telefone, n.whatsapp, n.instagram, n.site, n.horarios::jsonb, n.imagem_url, n.fotos, null, 'ABERTO AGORA'
from novas n
where not exists (select 1 from public.anuncios a where lower(a.titulo) = lower(n.titulo));